import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import type { SfxItem } from '@shared/api'
import { scoped } from './logger'
import { paths } from './paths'

const log = scoped('sfx')

/** Built-in sound effects shipped in resources/sfx (generated by scripts/gen-sfx.mjs). */
export function listSfx(): SfxItem[] {
  const manifest = join(paths.sfxDir(), 'index.json')
  if (!existsSync(manifest)) {
    log.warn('sfx manifest missing')
    return []
  }
  try {
    const items = JSON.parse(readFileSync(manifest, 'utf8')) as { id: string; category: string; file: string; duration: number }[]
    return items.map((i) => ({ id: i.id, category: i.category, duration: i.duration, path: join(paths.sfxDir(), i.file) }))
  } catch (err) {
    log.error('sfx manifest unreadable', err)
    return []
  }
}
